from collections import deque,Counter
R,C=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  v=grid[r][c]
  if v==2 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c));cells=[]
  while q:
   x,y=q.pop();cells.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=(x+dx,y+dy)
    if 0<=z[0]<R and 0<=z[1]<C and z not in seen and grid[z[0]][z[1]]==v:
     seen.add(z);q.append(z)
  comps.append((v,len(cells),(min(x for x,y in cells),min(y for x,y in cells),max(x for x,y in cells),max(y for x,y in cells))))
print(sorted(comps,key=lambda x:(x[2][0],x[2][1])))
